; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: ti83 (TI-83 Plus / 84 Plus (TI-OS)), starts in normal mode
; ============================================================

			org #9D95

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 40		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 0		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)
NTC_WINHOLE	equ 0		; 1 = the program is built round an Option Reserve range over the window #4000-#7FFF
NTC_BUFSIZE	equ 2048		; the library's buffer (ntc_buf: FileSystem, Memory.Copy): Option Buffer
NTC_CPMGFX	equ 0		; 1 = CP/M: Graphics draws on an Amstrad CPC's screen (2.2: #C000, Plus: block 1 from common memory)

ntc_start:
			di
			ld sp, ntc_ti_stack		; the platform's own real stack
			ld (ntc_csp), sp
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:

			; 31: Cls
			dw kw_cls

			; 32: Input "Your name"; nm
			dw kw_printstrvar, str0
			dw kw_inputstr, var_nm

			; 33: Print "Hello " & nm
			dw kw_printstrvar, str1
			dw kw_printstrvar, var_nm
			dw kw_printnl

			; 34: For i = 1 To 10
			dw kw_ltov, 1, var_i
for1_t:

			; 35: If i Mod 3 = 0 Then Print "fizz "; Else Print i; " ";
			dw kw_modvl, var_i, 3, tmp0
			dw kw_cpeqvl, tmp0, 0
			dw kw_goto_iffalse_n, if2_1
			dw kw_printstrvar, str2
			dw if2_e_go
if2_1:
			dw kw_printint, var_i
			dw kw_printstrvar, str3
if2_e:

			; 36: Next
			dw kw_next1l_n, var_i, 10, for1_t
for1_e:

			; 37: Print
			dw kw_printnl

			; 38: Print Shout(nm)
			dw p_shout_c, var_nm
			dw kw_printstrvar, var_shout_shout
			dw kw_printnl

			; 39: Break done
			dw bp_done_n

			; 40: End
			dw kw_printnl0
			dw kw_printstrvar, str4
			dw kw_waitkey
			dw kw_stop

; ============================================================
; function shout (normal mode)
; ============================================================

p_shout:

			; 43: Shout = UCase$(s) & "!"
			dw kw_strucase, stmp0, var_shout_s
			dw kw_strcpy, var_shout_shout, stmp0
			dw kw_strcat, var_shout_shout, str5
			dw p_shout_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

if2_e_go:			ld sp, if2_e
			jp ntc_xn

p_shout_c:		; call shout (normal)
			pop hl			; s
			ld de, var_shout_s
			ld b, 40
p_shout_si0:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_shout_si0_e
			inc hl
			inc de
			djnz p_shout_si0
			xor a
			ld (de), a
p_shout_si0_e:
			xor a
			ld (var_shout_shout), a
			ld (p_shout_rs), sp
			ld sp, p_shout
			jp ntc_xn
p_shout_r:		; end of shout
			ld sp, (p_shout_rs)
			jp ntc_xn

; ============================================================
; Breakpoints
; ============================================================

bp_done_n:			jp ntc_xn

; ============================================================
; Variables
; ============================================================

			db 40			; capacity
var_nm:			ds 41
var_i:			dw 0
			db 40			; capacity
var_shout_shout:			ds 41
p_shout_rs:			dw 0
			db 40			; capacity
var_shout_s:			ds 41
tmp0:			dw 0
			db 40			; capacity
stmp0:			ds 41

; ============================================================
; Strings
; ============================================================

str0:			db "Your name? ", 0
str1:			db "Hello ", 0
str2:			db "fizz ", 0
str3:			db " ", 0
str4:			db "Press a key", 0
str5:			db "!", 0

; ============================================================
; Keyword library (used)
; ============================================================

;## ntc_data @shared ntc_d_nmode
; ------------------------------------------------------------
; Scratch space: the core every program has (with ntc_d_nmode). The rest of
; the run time's variables are @data sections, each linked only when a
; linked section's code names one of its labels (no header lists them).
; They stay in this order: the keyword ROM's registry keeps each variable's
; address (a Library: ROM program has them as fixed addresses)
; ------------------------------------------------------------
ntc_next:		ret				; IX target that continues the thread
ntc_csp:		dw 0			; caller SP, for kw_stop (and the normal mode stack)
ntc_ip:			dw 0			; normal mode: thread position while out of the thread

;## ntc_d_nmode @data
ntc_nmode:		db 0			; 1 = running in normal mode (waits let interrupts in)

;## ntc_d_div @data
ntc_mode:		db 0			; div mode 0=quotient 1=remainder
ntc_sgnq:		db 0			; quotient sign (bit 7)
ntc_sgnr:		db 0			; remainder sign (bit 7)

;## ntc_d_lead @data
ntc_lead:		db 0			; printint: digit seen

;## ntc_d_icnt @data
ntc_icnt:		db 0			; gets: chars typed
ntc_icap:		db 0			; gets: the buffer's capacity

;## ntc_d_sptr @data
ntc_sptr:		dw 0			; printbuf: text pointer

;## ntc_d_iptr @data
ntc_iptr:		dw 0			; gets: buffer pointer
ntc_ilink:		dw 0			; gets: where to go when done

;## ntc_d_numbuf @data
ntc_numbuf:		ds 14			; printint / long print: digits (+ spaces for Option VBPrint)

;## kw_stop ntc_data ntc_plat_exit @shared
kw_stop:
			ld ix, ntc_stop_back
			jp ntc_plat_exit
ntc_stop_back:
			ld sp, (ntc_csp)
			ei
			ret

;## kw_waitkey ntc_data ntc_plat_key
; kw_waitkey - wait for a key (Option PressAnyKeyOnEnd, before kw_stop)
kw_waitkey:
			ld ix, ntc_next
			jp ntc_plat_getkey

;## ntc_xn ntc_data @shared
; normal mode "next": every normal mode keyword ends here (its ret
; became jp ntc_xn). Thread position to ntc_ip, real stack, one
; instruction with interrupts on, then back into the thread.
ntc_xn:
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ei
			nop					; an interrupt can be taken here
			di
			ld sp, (ntc_ip)
			ret

;## kw_goto_iffalse (normal mode copy)
;kw_goto_iffalse, <label>  - branch if NZ (false)
kw_goto_iffalse_n:
			pop hl
			jp z, ntc_xn
			ld sp, hl
			jp ntc_xn

;## ntc_for_jump (normal mode copy)
; tails for the FOR / NEXT keywords. DE = var value, HL = limit,
; SP = thread at the label word. Signed compare by flipping bit 15.
; ntc_for_gt: jump to the label if var > limit, else skip it
ntc_for_gt_n:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			or a
			sbc hl, de			; limit - var, carry = var > limit
			pop hl
			jp nc, ntc_xn
			ld sp, hl
			jp ntc_xn
; ntc_for_lt: jump to the label if var < limit, else skip it
ntc_for_lt_n:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			ex de, hl
			or a
			sbc hl, de			; var - limit, carry = var < limit
			pop hl
			jp nc, ntc_xn
			ld sp, hl
			jp ntc_xn
; ntc_for_le: jump to the label if var <= limit (loop again). A not 0: the
; step took var past 32767 (or -32768): the loop ends (ntc_for_ge too)
ntc_for_le_n:
			or a
			jr nz, ntc_for_end_n
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			or a
			sbc hl, de			; limit - var, no carry = var <= limit
			pop hl
			jp c, ntc_xn
			ld sp, hl
			jp ntc_xn
; ntc_for_ge: jump to the label if var >= limit (loop again)
ntc_for_ge_n:
			or a
			jr nz, ntc_for_end_n
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			ex de, hl
			or a
			sbc hl, de			; var - limit, no carry = var >= limit
			pop hl
			jp c, ntc_xn
			ld sp, hl
			jp ntc_xn
ntc_for_end_n:
			pop hl
			jp ntc_xn

;## kw_next1l (normal mode copy) ntc_for_jump
;kw_next1l, <var>, <literal limit>, <toplabel>
;  NEXT for STEP 1: inc var, back to the top while var <= limit
kw_next1l_n:
			pop hl
			inc (hl)
			ld e, (hl)
			inc hl
			jr nz, ntc_n1l_nc_n
			inc (hl)
ntc_n1l_nc_n:
			ld d, (hl)
			pop hl
			ld a, d					; A = #FF when it went past 32767 (#8000)
			xor #80
			or e
			sub 1
			sbc a, a
			jp ntc_for_le_n

;## kw_ltov
;kw_ltov, <literal>, <destvar>
kw_ltov:
			pop de
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## ntc_div ntc_data
; HL / DE signed, truncating. (ntc_mode) 0 = quotient, 1 = remainder.
; Remainder takes the dividend's sign. Divide by zero gives
; quotient 0, remainder = dividend. Pops destvar and stores.
ntc_div:
			ld a, d
			or e
			jr nz, ntc_div_nz
			ld a, (ntc_mode)
			or a
			jr nz, ntc_div_store
			ld hl, 0
			jr ntc_div_store
ntc_div_nz:
			ld a, h
			ld (ntc_sgnr), a
			xor d
			ld (ntc_sgnq), a
			bit 7, h
			jr z, ntc_div_hpos
			xor a
			sub l
			ld l, a
			sbc a, a
			sub h
			ld h, a
ntc_div_hpos:
			bit 7, d
			jr z, ntc_div_dpos
			xor a
			sub e
			ld e, a
			sbc a, a
			sub d
			ld d, a
ntc_div_dpos:
			ld a, h
			ld c, l
			ld hl, 0
			ld b, 16
ntc_div_loop:
			sla c
			rla
			adc hl, hl
			sbc hl, de
			jr nc, ntc_div_one
			add hl, de
			djnz ntc_div_loop
			jr ntc_div_done
ntc_div_one:
			inc c
			djnz ntc_div_loop
ntc_div_done:
			ld b, a
			ld a, (ntc_mode)
			or a
			jr z, ntc_div_q
			ld a, (ntc_sgnr)
			jr ntc_div_sign
ntc_div_q:
			ld h, b
			ld l, c
			ld a, (ntc_sgnq)
ntc_div_sign:
			rla
			jr nc, ntc_div_store
			xor a
			sub l
			ld l, a
			sbc a, a
			sub h
			ld h, a
ntc_div_store:
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_divvl ntc_div
;kw_divvl, <var>, <literal>, <destvar>
kw_divvl:
			xor a
			ld (ntc_mode), a
ntc_divvl:
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			pop de
			jp ntc_div

;## kw_modvl kw_divvl
;kw_modvl, <var>, <literal>, <destvar>
kw_modvl:
			ld a, 1
			ld (ntc_mode), a
			jp ntc_divvl

;## ntc_cmp
ntc_cmp_slt:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ult:
			ex de, hl
			or a
			sbc hl, de
			sbc a, a
			inc a
			ret
ntc_cmp_sge:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_uge:
			ex de, hl
			or a
			sbc hl, de
			sbc a, a
			ret
ntc_cmp_sgt:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ugt:
			or a
			sbc hl, de
			sbc a, a
			inc a
			ret
ntc_cmp_sle:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ule:
			or a
			sbc hl, de
			sbc a, a
			ret
ntc_cmp_eq:
			or a
			sbc hl, de
			ret
ntc_cmp_ne:
			or a
			sbc hl, de
			jr z, ntc_cmp_ne_f
			xor a
			ret
ntc_cmp_ne_f:
			or 1
			ret

;## kw_cpeqvl ntc_cmp
kw_cpeqvl:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			jp ntc_cmp_eq

;## kw_strcpy
;kw_strcpy, <destaddr>, <srcaddr>  - cut at the destination's capacity byte
kw_strcpy:
			pop de
			pop hl
			dec de
			ld a, (de)
			ld b, a
			inc de
ntc_strcpy_loop:
			ld a, (hl)
			ld (de), a
			or a
			ret z
			inc hl
			inc de
			djnz ntc_strcpy_loop
			xor a
			ld (de), a
			ret

;## kw_strcat
;kw_strcat, <destaddr>, <srcaddr>  - cut at the destination's capacity byte
kw_strcat:
			pop de
			dec de
			ld a, (de)
			ld b, a
			inc de
ntc_strcat_end:
			ld a, (de)
			or a
			jr z, ntc_strcat_copy
			inc de
			djnz ntc_strcat_end
			pop hl
			ret
ntc_strcat_copy:
			pop hl
ntc_strcat_loop:
			ld a, (hl)
			ld (de), a
			or a
			ret z
			inc hl
			inc de
			djnz ntc_strcat_loop
			xor a
			ld (de), a
			ret

;## ntc_printbuf ntc_data ntc_plat_screen
; print the 0 terminated ASCII text at (ntc_sptr), then ret (thread)
ntc_printbuf:
			ld hl, (ntc_sptr)
			ld a, (hl)
			or a
			ret z
			inc hl
			ld (ntc_sptr), hl
			ld ix, ntc_printbuf
			jp ntc_plat_putc

;## kw_printstrvar ntc_printbuf
;kw_printstrvar, <straddr>
kw_printstrvar:
			pop hl
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## ntc_itoa ntc_data
; HL = signed value, DE = buffer: writes the digits and a 0 (DE ends on
; the 0). jp (ix) back. Uses A, BC, IY.
ntc_itoa:
			bit 7, h
			jr z, ntc_ia_pos
			ld a, '-'
			ld (de), a
			inc de
			xor a
			sub l
			ld l, a
			sbc a, a
			sub h
			ld h, a
ntc_ia_pos:
			xor a
			ld (ntc_lead), a
			ld iy, ntc_pow10
ntc_ia_pow:
			ld c, (iy+0)
			ld b, (iy+1)
			ld a, b
			or c
			jr z, ntc_ia_last
			ld a, '0' - 1
ntc_ia_sub:
			inc a
			and a
			sbc hl, bc
			jr nc, ntc_ia_sub
			add hl, bc
			cp '0'
			jr nz, ntc_ia_out
			ld b, a
			ld a, (ntc_lead)
			or a
			ld a, b
			jr z, ntc_ia_skip
ntc_ia_out:
			ld (de), a
			inc de
			ld a, 1
			ld (ntc_lead), a
ntc_ia_skip:
			inc iy
			inc iy
			jr ntc_ia_pow
ntc_ia_last:
			ld a, l
			add a, '0'
			ld (de), a
			inc de
			xor a
			ld (de), a
			jp (ix)
ntc_pow10:		dw 10000, 1000, 100, 10, 0

;## kw_printint ntc_printbuf ntc_itoa
;kw_printint, <var>  - signed decimal
kw_printint:
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ld de, ntc_numbuf
			ld ix, ntc_pi_done
			jp ntc_itoa
ntc_pi_done:
			ld hl, ntc_numbuf
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## kw_printnl0 ntc_data ntc_plat_screen
;kw_printnl0  - new line unless the cursor is at the start of a line
kw_printnl0:
			ld a, (ntc_curx)
			or a
			ret z
			ld ix, ntc_next
			jp ntc_plat_newline

;## kw_printnl ntc_data ntc_plat_screen
;kw_printnl
kw_printnl:
			ld ix, ntc_next
			jp ntc_plat_newline

;## ntc_gets ntc_data ntc_plat_screen ntc_plat_key
; line input with echo and DEL (or backspace). HL = buffer (its capacity in the byte
; before it), DE = where to
; jp when done (after the newline). 40 chars max, 0 terminated.
ntc_gets:
			ld (ntc_iptr), hl
			ld (ntc_ilink), de
			dec hl
			ld a, (hl)			; the buffer's capacity
			ld (ntc_icap), a
			xor a
			ld (ntc_icnt), a
ntc_gs_wait:
			ld ix, ntc_gs_key
			jp ntc_plat_getkey
ntc_gs_key:
			cp 13
			jr z, ntc_gs_done
			cp 127
			jr z, ntc_gs_del
			cp 8
			jr z, ntc_gs_del
			cp 32
			jr c, ntc_gs_wait
			ld c, a
			ld a, (ntc_icap)
			ld b, a
			ld a, (ntc_icnt)
			cp b
			jr nc, ntc_gs_wait
			inc a
			ld (ntc_icnt), a
			ld hl, (ntc_iptr)
			ld (hl), c
			inc hl
			ld (ntc_iptr), hl
			ld a, c
			ld ix, ntc_gs_wait
			jp ntc_plat_putc
ntc_gs_del:
			ld a, (ntc_icnt)
			or a
			jr z, ntc_gs_wait
			dec a
			ld (ntc_icnt), a
			ld hl, (ntc_iptr)
			dec hl
			ld (ntc_iptr), hl
			ld ix, ntc_gs_wait
			jp ntc_plat_backspace
ntc_gs_done:
			ld hl, (ntc_iptr)
			ld (hl), 0
			ld ix, (ntc_ilink)
			jp ntc_plat_newline

;## kw_inputstr ntc_gets
;kw_inputstr, <straddr>
kw_inputstr:
			pop hl
			ld de, ntc_next
			jp ntc_gets

;## kw_cls ntc_data ntc_plat_screen
;kw_cls
kw_cls:
			ld ix, ntc_next
			jp ntc_plat_cls

;## kw_strucase
;kw_strucase, <dest>, <src>  - UCase$
kw_strucase:
			pop de
			pop hl
ntc_uc_loop:
			ld a, (hl)
			cp 'a'
			jr c, ntc_uc_put
			cp 'z' + 1
			jr nc, ntc_uc_put
			sub 32
ntc_uc_put:
			ld (de), a
			or a
			ret z
			inc hl
			inc de
			jr ntc_uc_loop

;## ntc_plat_data
; ------------------------------------------------------------
; TI-OS bcall equates - standard ti83plus.inc values.  ;!!TI confirm every one
; against your ti83plus.inc (the include can't be downloaded in this box).
; ------------------------------------------------------------
_PutC            equ #4504   ; A = char at cursor, advance curCol            ;!!TI
_PutS            equ #450A   ; HL = zero-terminated string                   ;!!TI
_NewLine         equ #452E   ; CR+LF, scroll if needed                       ;!!TI
_ClrLCDFull      equ #4540   ; clear the whole LCD                           ;!!TI
_HomeUp          equ #4558   ; curRow = curCol = 0                           ;!!TI
_GetCSC          equ #4018   ; A = scan code (0 = none), non-blocking        ;!!TI
_GetKey          equ #4972   ; A = key code, blocking (2nd/alpha handled)    ;!!TI
_JForceCmdNoChar equ #4027   ; clean return to the homescreen (exit)         ;!!TI
curRow           equ #844B   ; OS text cursor row  (0-7)                     ;!!TI
curCol           equ #844C   ; OS text cursor col  (0-15)                    ;!!TI

ntc_curx:		db 0			; column mirror (0 based) - counted for Tab
ntc_cury:		db 0			; row mirror (0 based)
ntc_scols:		db 16			; columns (large-font grid)                 ;!!TI
ntc_ti_stack	equ ntc_end + 256	; the real stack: the 256 bytes above the program image.
									; SP is swapped to it only for a bcall (which is shallow).

;## ntc_ti_call ntc_plat_data ntc_data @shared
; ------------------------------------------------------------
; ntc_ti_call - IY = a real-stack routine (it may bcall). SP is the thread;
; swap it to the real stack (ntc_csp), call the routine, swap back, keep IX.
; This is the MSX ntc_vcall pattern retargeted to TI-OS. Registers pass
; straight through to/from the routine (A = char for putc, A = key out, ...).
; ------------------------------------------------------------
ntc_ti_call:
			ld (ntc_tiix), ix
			ld (ntc_tisp), sp
			ld sp, (ntc_csp)
			call ntc_ti_call_jp
			ld sp, (ntc_tisp)
			ld ix, (ntc_tiix)
			jp (ix)
ntc_ti_call_jp:
			jp (iy)
ntc_tiix:		dw 0			; IX over the call
ntc_tisp:		dw 0			; the thread's SP over the call

;## ntc_plat_screen ntc_ti_call ntc_plat_data ntc_data
; ntc_plat_putc - A = character to the screen (_PutC), mirror curCol into ntc_curx
ntc_plat_putc:
			ld iy, ntc_tir_putc
			jp ntc_ti_call
ntc_tir_putc:
			rst #28
			dw _PutC				; A = char; OS advances/wraps curCol
			ld a, (curCol)
			ld (ntc_curx), a
			ret

; ntc_plat_newline - _NewLine, then curx mirror = 0
ntc_plat_newline:
			ld iy, ntc_tir_newline
			jp ntc_ti_call
ntc_tir_newline:
			rst #28
			dw _NewLine
			xor a
			ld (ntc_curx), a
			ret

;## ntc_plat_backspace @unit ntc_plat_screen ntc_ti_call ntc_plat_data ntc_data
; ntc_plat_backspace - back up a column, blank it, back up again (large font)
ntc_plat_backspace:
			ld iy, ntc_tir_bs
			jp ntc_ti_call
ntc_tir_bs:
			ld a, (curCol)
			or a
			ret z					; already at column 0: nothing
			dec a
			ld (curCol), a			; step back
			ld a, ' '
			rst #28
			dw _PutC				; blank the cell (advances curCol again)
			ld a, (curCol)
			or a
			ret z
			dec a
			ld (curCol), a			; step back over the blank
			ld (ntc_curx), a
			ret

;## ntc_plat_cls @unit ntc_plat_screen ntc_ti_call ntc_plat_data ntc_data
; ntc_plat_cls - clear the LCD and home the cursor
ntc_plat_cls:
			ld iy, ntc_tir_cls
			jp ntc_ti_call
ntc_tir_cls:
			rst #28
			dw _ClrLCDFull
			rst #28
			dw _HomeUp
			xor a
			ld (ntc_curx), a
			ret

;## ntc_plat_key ntc_ti_call ntc_data
; ntc_plat_scankey - A = key or 0 (non-blocking, _GetCSC).
; ;!!TI _GetCSC returns a TI SCAN CODE (skEnter, sk0..., skGraph), NOT ASCII.
; A scancode->ASCII map (below, stubbed) is needed before Inkey reads sanely.
ntc_plat_scankey:
			ld iy, ntc_tir_scan
			jp ntc_ti_call
ntc_tir_scan:
			rst #28
			dw _GetCSC				; A = scan code or 0
			; ;!!TI map A (scan code) -> ASCII here; raw code passed through for now
			ret

; ntc_plat_getkey - wait for a key (poll _GetCSC so interrupts aren't required)
ntc_plat_getkey:
			ld iy, ntc_tir_getk
			jp ntc_ti_call
ntc_tir_getk:
			rst #28
			dw _GetCSC
			or a
			jr z, ntc_tir_getk
			; ;!!TI map A (scan code) -> ASCII here too
			ret

;## ntc_plat_exit ntc_ti_call ntc_plat_data ntc_data
; ntc_plat_exit - clean return to the homescreen. SP is the mangled thread, so
; a plain ret can't go back; _JForceCmdNoChar resets the OS to the homescreen
; regardless of the stack. Swap to the real stack first.
ntc_plat_exit:
			ld sp, (ntc_csp)
			rst #28
			dw _JForceCmdNoChar		; does not return
			ret						; (unreached)                            ;!!TI


ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bssfrom	equ ntc_end
ntc_bss		equ ntc_bssfrom
ntc_bss_size	equ 0
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
ntc_memtab	equ ntc_free		; the Memory class's tables
